using BARANG.Core.Domain.BusinessAnalysis;
using BARANG.Core.Domain.Catalog;
using BARANG.Core.Domain.Customers;
using BARANG.Core.Domain.Orders;
using BARANG.Core.Domain.Files;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BARANG.Core.Infrastructure.Persistence.Configurations;

internal static class BusinessProfileConfiguration
{
    public static void Base<T>(EntityTypeBuilder<T> b,string table) where T:class
    {b.ToTable(table);b.HasKey("Id");b.Property<Guid>("Id").HasColumnName("id");b.Property<Guid>("CompanyId").HasColumnName("company_id");b.Property<DateTimeOffset>("UpdatedAtUtc").HasColumnName("updated_at_utc");b.Property<long>("Version").HasColumnName("version").IsConcurrencyToken();b.HasAlternateKey("CompanyId","Id");}
}
internal sealed class CustomerBusinessProfileConfiguration:IEntityTypeConfiguration<CustomerBusinessProfile>
{public void Configure(EntityTypeBuilder<CustomerBusinessProfile>b){BusinessProfileConfiguration.Base(b,"customer_business_profiles");b.Property(x=>x.CustomerId).HasColumnName("customer_id");b.Property(x=>x.DateOfBirth).HasColumnName("date_of_birth");b.Property(x=>x.EconomicCode).HasColumnName("economic_code").HasMaxLength(64);b.Property(x=>x.CreditLimit).HasColumnName("credit_limit").HasPrecision(18,2);b.Property(x=>x.PaymentTermsDays).HasColumnName("payment_terms_days");b.Property(x=>x.BusinessDetails).HasColumnName("business_details").HasMaxLength(1000);b.HasIndex(x=>new{x.CompanyId,x.CustomerId}).IsUnique();b.HasOne<Customer>().WithMany().HasForeignKey(x=>new{x.CustomerId,x.CompanyId}).HasPrincipalKey(x=>new{x.Id,x.CompanyId}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class ProductTechnicalProfileConfiguration:IEntityTypeConfiguration<ProductTechnicalProfile>
{public void Configure(EntityTypeBuilder<ProductTechnicalProfile>b){BusinessProfileConfiguration.Base(b,"product_technical_profiles");b.Property(x=>x.ProductId).HasColumnName("product_id");b.Property(x=>x.ProductVariantId).HasColumnName("product_variant_id");b.Property(x=>x.BrandCode).HasColumnName("brand_code").HasMaxLength(50);b.Property(x=>x.MaterialCode).HasColumnName("material_code").HasMaxLength(50);b.Property(x=>x.GenderCode).HasColumnName("gender_code").HasMaxLength(50);b.Property(x=>x.FitCode).HasColumnName("fit_code").HasMaxLength(50);b.Property(x=>x.StyleCode).HasColumnName("style_code").HasMaxLength(50);b.Property(x=>x.TechnicalAttributes).HasColumnName("technical_attributes").HasMaxLength(2000);b.HasIndex(x=>new{x.CompanyId,x.ProductId,x.ProductVariantId}).IsUnique().AreNullsDistinct(false);b.HasOne<Product>().WithMany().HasForeignKey(x=>new{x.ProductId,x.CompanyId}).HasPrincipalKey(x=>new{x.Id,x.CompanyId}).OnDelete(DeleteBehavior.Restrict);b.HasOne<ProductVariant>().WithMany().HasForeignKey(x=>new{x.ProductVariantId,x.CompanyId}).HasPrincipalKey(x=>new{x.Id,x.CompanyId}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class OrderBusinessProfileConfiguration:IEntityTypeConfiguration<OrderBusinessProfile>
{public void Configure(EntityTypeBuilder<OrderBusinessProfile>b){BusinessProfileConfiguration.Base(b,"order_business_profiles");b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.ShippingMethodCode).HasColumnName("shipping_method_code").HasMaxLength(50);b.Property(x=>x.PackagingTypeCode).HasColumnName("packaging_type_code").HasMaxLength(50);b.Property(x=>x.IncludeInvoiceInPackage).HasColumnName("include_invoice_in_package");b.Property(x=>x.OrderTypeCode).HasColumnName("order_type_code").HasMaxLength(50);b.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(2000);b.HasIndex(x=>new{x.CompanyId,x.OrderId}).IsUnique();b.HasOne<Order>().WithMany().HasForeignKey(x=>new{x.OrderId,x.CompanyId}).HasPrincipalKey(x=>new{x.Id,x.CompanyId}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class PrintTechnicalProfileConfiguration:IEntityTypeConfiguration<PrintTechnicalProfile>
{public void Configure(EntityTypeBuilder<PrintTechnicalProfile>b){BusinessProfileConfiguration.Base(b,"print_technical_profiles");b.Property(x=>x.OrderPrintOperationId).HasColumnName("order_print_operation_id");b.Property(x=>x.DirectionCode).HasColumnName("direction_code").HasMaxLength(50);b.Property(x=>x.PrintSizeCode).HasColumnName("print_size_code").HasMaxLength(50);b.Property(x=>x.PrintCount).HasColumnName("print_count");b.Property(x=>x.PrinterEquipmentId).HasColumnName("printer_equipment_id");b.Property(x=>x.HeatPressEquipmentId).HasColumnName("heat_press_equipment_id");b.Property(x=>x.Specifications).HasColumnName("specifications").HasMaxLength(2000);b.HasIndex(x=>new{x.CompanyId,x.OrderPrintOperationId}).IsUnique();b.HasOne<OrderPrintOperation>().WithMany().HasForeignKey(x=>new{x.OrderPrintOperationId,x.CompanyId}).HasPrincipalKey(x=>new{x.Id,x.CompanyId}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Equipment>().WithMany().HasForeignKey(x=>new{x.PrinterEquipmentId,x.CompanyId}).HasPrincipalKey(x=>new{x.Id,x.CompanyId}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Equipment>().WithMany().HasForeignKey(x=>new{x.HeatPressEquipmentId,x.CompanyId}).HasPrincipalKey(x=>new{x.Id,x.CompanyId}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class OrderItemTechnicalSnapshotConfiguration:IEntityTypeConfiguration<OrderItemTechnicalSnapshot>
{public void Configure(EntityTypeBuilder<OrderItemTechnicalSnapshot>b){b.ToTable("order_item_technical_snapshots");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.CompanyId).HasColumnName("company_id");b.Property(x=>x.OrderItemId).HasColumnName("order_item_id");b.Property(x=>x.BrandCode).HasColumnName("brand_code").HasMaxLength(50);b.Property(x=>x.MaterialCode).HasColumnName("material_code").HasMaxLength(50);b.Property(x=>x.GenderCode).HasColumnName("gender_code").HasMaxLength(50);b.Property(x=>x.FitCode).HasColumnName("fit_code").HasMaxLength(50);b.Property(x=>x.StyleCode).HasColumnName("style_code").HasMaxLength(50);b.Property(x=>x.TechnicalAttributes).HasColumnName("technical_attributes").HasMaxLength(2000);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.HasIndex(x=>new{x.CompanyId,x.OrderItemId}).IsUnique();b.HasOne<OrderItem>().WithMany().HasForeignKey(x=>new{x.OrderItemId,x.CompanyId}).HasPrincipalKey(x=>new{x.Id,x.CompanyId}).OnDelete(DeleteBehavior.Restrict);}}
